\label{lem_monotone}
Under Assumption~\ref{assumption_null_cone_foliation}, the following hold.
\begin{enumerate}[label=(\alph*),leftmargin=*]
\item (Level sets) For every $s\in I$,
\begin{equation}\label{eq:levelsets}
J^+(\gamma(s))\cap\mathsf{D}_\gamma=\{f\ge s\},
\qquad
I^+(\gamma(s))\cap\mathsf{D}_\gamma=\{f>s\}.
\end{equation}

\item (Monotonicity) Let $x,y\in\mathsf{D}_\gamma$. Then
\begin{equation}\label{eq:mono}
y\in J^+(x)\ \Longrightarrow\ f(y)\ge f(x),
\qquad
y\in I^+(x)\ \Longrightarrow\ f(y)>f(x).
\end{equation}
In particular, for every $\tau\in I$,
\begin{equation*}
J^+(\mathcal{H}_{\tau})\cap\mathsf{D}_\gamma\subset\{f\ge\tau\}.
\end{equation*}
\item (Time orientation) The vector field $L=-\nabla_gf$ is future-directed.
\end{enumerate}

We use the following standard facts on the globally hyperbolic manifold $\mathcal{M}$ \cite{oneill1983}. For every $p\in\mathcal{M}$, the set $J^+(p)$ is closed and the set $I^+(p)$ is open. Moreover, the push-up property holds (see the footnote in Remark~\ref{rem_D_globhyp}): for $x,y,z\in\mathcal{M}$,
\begin{equation}\label{eq:pushup}
x\ll y\le z
\quad\text{or}\quad
x\le y\ll z
\qquad\Longrightarrow\qquad
x\ll z.
\end{equation}
Finally, since $\gamma$ is a future-directed timelike curve,
\begin{equation}\label{eq:gamma_order}
\gamma(s)\ll\gamma(s')\qquad\text{for } s<s'.
\end{equation}

(a) Let $x\in\mathsf{D}_\gamma$ and set $\sigma=f(x)$. By Assumption~\ref{assumption_null_cone_foliation},
\begin{equation*}
x\in\mathcal H_\sigma\subset\partial J^+(\gamma(\sigma)).
\end{equation*}
Since $J^+(\gamma(\sigma))$ is closed, its boundary is contained in it. Since $I^+(\gamma(\sigma))$ is open and contained in $J^+(\gamma(\sigma))$, it does not meet $\partial J^+(\gamma(\sigma))$. Hence
\begin{equation}\label{eq:AB}
\gamma(\sigma)\le x
\qquad\text{and}\qquad
\gamma(\sigma)\not\ll x.
\end{equation}
Now fix $s\in I$ and compare $\sigma$ with $s$.

If $\sigma>s$, then \eqref{eq:gamma_order} and \eqref{eq:AB} give
\begin{equation*}
\gamma(s)\ll\gamma(\sigma)\le x,
\end{equation*}
so $\gamma(s)\ll x$ by \eqref{eq:pushup}. In particular $\gamma(s)\le x$.

If $\sigma=s$, then $\gamma(s)\le x$ and $\gamma(s)\not\ll x$, by \eqref{eq:AB}.

If $\sigma<s$, then $\gamma(s)\not\le x$. Indeed, otherwise
\begin{equation*}
\gamma(\sigma)\ll\gamma(s)\le x,
\end{equation*}
and \eqref{eq:pushup} gives $\gamma(\sigma)\ll x$, which contradicts \eqref{eq:AB}. A fortiori, $\gamma(s)\not\ll x$.

Thus
\begin{equation*}
\gamma(s)\le x\iff f(x)\ge s,
\qquad
\gamma(s)\ll x\iff f(x)>s,
\end{equation*}
which is \eqref{eq:levelsets}.

(b) Let $x,y\in\mathsf{D}_\gamma$ with $y\in J^+(x)$, and set $s=f(x)$. By (a), $\gamma(s)\le x$, hence
\begin{equation*}
\gamma(s)\le x\le y.
\end{equation*}
So $\gamma(s)\le y$, and $f(y)\ge s$ by (a). If moreover $y\in I^+(x)$, then
\begin{equation*}
\gamma(s)\le x\ll y,
\end{equation*}
so $\gamma(s)\ll y$ by \eqref{eq:pushup}, and $f(y)>s$ by (a). Finally, if $y\in J^+(\mathcal{H}_{\tau})\cap\mathsf{D}_\gamma$, then $y\in J^+(x)$ for some $x\in\mathcal{H}_{\tau}$, and $f(y)\ge f(x)=\tau$.

(c) Let $x\in\mathsf{D}_\gamma$ and let $Y\in T_x\mathcal{M}$ be future-directed timelike. Since $\mathsf{D}_\gamma$ is open, there is a future-directed timelike curve $c\colon[0,\delta)\to\mathsf{D}_\gamma$ with $c(0)=x$ and $\dot c(0)=Y$. For $0<t<\delta$ we have $c(t)\in I^+(x)$, so $f(c(t))>f(x)$ by (b). Hence
\begin{equation*}
df(Y)=\frac{d}{dt}f(c(t))\Big|_{t=0}\ge0.
\end{equation*}
The vector $\nabla_gf$ is normal to the null hypersurfaces $\mathcal H_\tau$, so it is null, and it is nonzero since $df\ne0$. A nonzero null vector is not orthogonal to a timelike vector, so $df(Y)=g(\nabla_gf,Y)\ne0$. Therefore
\begin{equation*}
g(L,Y)=-df(Y)<0,
\end{equation*}
and the null vector $L$ is future-directed.

\label{lem:key}
Let $\alpha,v\in C^\infty(\mathsf{D}_\gamma)$. Then, in $\mathsf{D}_\gamma$,
\begin{equation}
\begin{aligned}
  P\bigl(\alpha\,\delta(\varphi)+v\,H(\varphi)\bigr)
  ={}&
  \bigl(2L(\alpha)+\theta\alpha\bigr)\delta'(\varphi)
  \\
  &+
  \bigl(P\alpha+2L(v)+\theta v\bigr)\delta(\varphi)
  +
  (Pv)H(\varphi).
\end{aligned}
\label{eq:key}
\end{equation}

Since $\Box_g=-\operatorname{div}_g\nabla$, $g(\nabla\varphi,\nabla\varphi)=0$, $L=-\nabla\varphi$ and $\theta=\Box_g\varphi$, for $a\in C^\infty(\mathsf{D}_\gamma)$ and $F\in\mathcal D'(\mathbb R)$ we have
\begin{equation}\label{eq:PaF}
P\bigl(a\,F(\varphi)\bigr)=F(\varphi)\,Pa+F'(\varphi)\,\bigl(2L(a)+\theta a\bigr).
\end{equation}
In particular
\begin{equation}
  \Box_gH(\varphi)=\theta\,\delta(\varphi),
  \qquad
  \Box_g\delta(\varphi)=\theta\,\delta'(\varphi).
  \label{eq:box-H-delta}
\end{equation}
With $F=H$ and $F=\delta$, \eqref{eq:PaF} yields
\begin{equation}
  P(v\,H(\varphi))
  =
  (Pv)\,H(\varphi)
  +
  (2L(v)+\theta v)\,\delta(\varphi),
  \label{eq:PvH}
\end{equation}
and
\begin{equation}
  P(\alpha\,\delta(\varphi))
  =
  (P\alpha)\,\delta(\varphi)
  +
  (2L(\alpha)+\theta\alpha)\,\delta'(\varphi).
  \label{eq:Palpha}
\end{equation}
Adding \eqref{eq:PvH} and \eqref{eq:Palpha} proves \eqref{eq:key}.

\label{prop_prog_wave}
Let $V$ be the unique solution of~\eqref{eq_wave_lorentz}. Then, there exist functions $\alpha,v\in C^\infty(\mathsf{D})$, with $\alpha$ vanishing near $\gamma(I)$,
such that
\begin{equation}
  V=\alpha\,\delta(\varphi)+v\,H(\varphi)
  \qquad\text{in }\mathsf{D}.
  \label{eq:main}
\end{equation}
Moreover, $\alpha$ satisfies
\begin{equation}
  2L(\alpha)+\theta\alpha=\chi
  \qquad\text{in }\mathsf{D}_\gamma,
  \label{eq:alpha}
\end{equation}
and there is $\delta_\alpha>0$ such that
\begin{equation}
  \alpha\ge\delta_\alpha\qquad\text{on }K.
  \label{eq:alpha-lower}
\end{equation}

\textbf{1. The ansatz and the transport equations.}
We look for a parametrix of the form
\begin{equation}\label{def_of_parametrix_r}
R_\infty=\alpha\,\delta(\varphi)+\widetilde v\,H(\varphi),
\qquad
\widetilde v\sim\sum_{k\ge0}w_k\,\varphi^k\quad\text{near }\mathcal{H}_{\tau},
\end{equation}
with smooth functions $\alpha,w_0,w_1,\dots$, such that $PR_\infty-\chi\,\delta'(\varphi)$ is smooth. Then $V-R_\infty$ solves a wave equation with a smooth source, so it is smooth.

To find the equations for $\alpha$ and the $w_k$, let
\begin{equation*}
v_N=\sum_{k=0}^Nw_k\varphi^k .
\end{equation*}
Since $L\varphi=0$, \eqref{eq:PaF} gives
\begin{equation*}
P(w_k\varphi^k)=\varphi^kPw_k+k\varphi^{k-1}(2Lw_k+\theta w_k),
\qquad
(2L+\theta)v_N=\sum_{k=0}^N\varphi^k(2L+\theta)w_k .
\end{equation*}
As $\varphi^k\delta(\varphi)=0$ for $k\ge1$, Lemma~\ref{lem:key} gives
\begin{equation}\label{eq:ansatz}
\begin{aligned}
&P\bigl(\alpha\,\delta(\varphi)+v_N\,H(\varphi)\bigr)-\chi\,\delta'(\varphi)\\
&\quad=(2L\alpha+\theta\alpha-\chi)\,\delta'(\varphi)+(2Lw_0+\theta w_0+P\alpha)\,\delta(\varphi)\\
&\qquad+\sum_{k=1}^N\varphi^{k-1}\bigl(k(2Lw_k+\theta w_k)+Pw_{k-1}\bigr)H(\varphi)+\varphi^N(Pw_N)\,H(\varphi).
\end{aligned}
\end{equation}
So we impose the transport equations
\begin{equation}\label{eq:recursion}
\left\{
\begin{aligned}
&2L\alpha+\theta\alpha=\chi,\\
&2Lw_0+\theta w_0=-P\alpha,\\
&k\,(2Lw_k+\theta w_k)=-Pw_{k-1},\qquad k\ge1.
\end{aligned}
\right.
\end{equation}
Then only the last term of \eqref{eq:ansatz} remains. In particular,
\begin{equation}\label{eq:Pwk}
Pv_N=\varphi^N\,Pw_N .
\end{equation}
This error is only in $C^{N-1}$ and will be removed by letting $N\to\infty$ via Borel's theorem.

\medskip\noindent
\textbf{2. Solving the transport equations on all leaves.}
Each equation in \eqref{eq:recursion} has the form
\begin{equation*}
2La+\theta a=b,
\end{equation*}
with $b$ given by the previous equations. Since $L$ is tangent to the leaves, this is an ODE along each null generator. The generator through $x\in\mathsf{D}_\gamma$ is the null geodesic from the vertex $\gamma(f(x))$ to $x$. We solve it on every generator of every leaf $\mathcal H_s$, $s\in I$ and the solutions are then defined on all of $\mathsf{D}_\gamma$. This is important since $Pa$ involves derivatives of $a$ in directions transversal to $\mathcal H_\tau$.

Let $\lambda\colon(s_0,s_1)\to\mathsf{D}_\gamma$ be a generator, with $\dot\lambda=L\circ\lambda$ and $\lambda(s)$ tending to its vertex as $s\to s_0$. For $b$ vanishing near $\gamma(I)$, the unique solution along $\lambda$ that vanishes near the vertex is
\begin{equation}
  a(\lambda(s))
  =
  \frac{1}{2}
  \int_{s_0}^{s}
  b(\lambda(\sigma))
  \exp\!\left(
  -\frac{1}{2}\int_\sigma^s\theta(\lambda(r))\,dr
  \right)
  d\sigma .
  \label{eq:alpha-explicit}
\end{equation}
It is smooth on $\mathsf{D}_\gamma$, by smooth dependence of the flow of $L$ on the initial point.

It remains to check that the right-hand sides vanish near \textit{a whole neighbourhood} of $\gamma(I)$ in $\mathsf{D}$. By \eqref{eq:alpha-explicit}, $a(x)$ depends only on $b$ along the generator segment from $\gamma(f(x))$ to $x$. By Lemma~\ref{lem_monotone}, the points $y$ of this segment satisfy
\begin{equation}\label{eq:segment}
\gamma(f(x))\le y\le x .
\end{equation}
Let $s\in I$. Since $\mathcal{M}$ is globally hyperbolic, there is $\varepsilon>0$ such that
\begin{equation*}
J^+(\gamma(s-\varepsilon))\cap J^-(\gamma(s+\varepsilon))\cap\operatorname{supp}\chi=\emptyset .
\end{equation*}
Let
\begin{equation*}
\mathcal U_s=I^+(\gamma(s-\varepsilon))\cap I^-(\gamma(s+\varepsilon)),
\end{equation*}
an open neighbourhood of $\gamma(s)$ on which $\chi=0$. If $x\in\mathcal U_s\cap\mathsf{D}_\gamma$, then $f(x)>s-\varepsilon$ by Lemma~\ref{lem_monotone}(a). So, by \eqref{eq:segment}, every point $y$ of the generator segment to $x$ satisfies
\begin{equation*}
\gamma(s-\varepsilon)\ll\gamma(f(x))\le y\le x\ll\gamma(s+\varepsilon),
\end{equation*}
and hence $y\in\mathcal U_s$. Now $\alpha$ is determined by~\eqref{eq:alpha-explicit} for $b=\chi$ and it vanishes in $\cup_{s \in I} \mathcal U _s$ which is a neighbourhood of $\gamma(I)$. Moreover, the lower bound~\eqref{eq:alpha-lower} is an immediate consequence of the same formula
\begin{equation*}
\alpha(x)=\frac12\int_{s_0}^{0}\chi(\lambda(\sigma))\exp\Bigl(-\frac12\int_\sigma^0\theta(\lambda(r))\,dr\Bigr)d\sigma,
\end{equation*}
combined with the assumption~\ref{assumption_sources} on $\chi$. Indeed, since each generator meets the set $\{\chi >0\}$ we have that $\alpha(x)>0$ for all $x \in K$ and hence the lower bound by compactness.



Once $\alpha$ is constructed the subsequent $w_k$ are determined by solving the transport equations~\eqref{eq:recursion}. They vanish near $\gamma(I)$, and we extend them by zero to $\mathsf{D}$. In the same way, they vanish in the open set $\mathsf{D}_\gamma\setminus J^+(\operatorname{supp}\chi)$: by \eqref{eq:segment}, the generator segment to a point $x$ of this set lies in $J^-(x)$, hence in this set. Thus
\begin{equation*}
\operatorname{supp}\alpha\cup\bigcup_{k\ge0}\operatorname{supp} w_k\subset J^+(\operatorname{supp}\chi).
\end{equation*}



\medskip\noindent
\textbf{3. The parametrix.}
Since $d\varphi=df\neq0$, $\varphi$ can be used as a local coordinate near $\mathcal{H}_{\tau}$. By Borel's theorem~\cite[Theorem 1.2.6]{hormander1990}, applied in the variable $\varphi$, there is a function $\widetilde v_0$, smooth in a neighbourhood $\mathcal O$ of $\mathcal{H}_{\tau}$ in $\mathsf{D}_\gamma$, with prescribed Taylor coefficients in $\varphi$:
\begin{equation}
  \widetilde v_0-\sum_{k<N}w_k\varphi^k\in\varphi^N\,C^\infty(\mathcal O)\qquad\text{for every }N .
  \label{eq:borel}
\end{equation}
The function $\widetilde v_0$ is not yet what we need since it is defined only in $\mathcal O$, and only its Taylor coefficients on $\mathcal{H}_{\tau}$ are prescribed. We use a cut-off to extend to the whole $\mathsf{D}$.

Let $\mathcal N\subset\mathsf{D}$ be an open neighbourhood of $\gamma(I)$ on which all $w_k$ vanish. We pick $\vartheta\in C^\infty(\mathsf{D})$ with
\begin{equation*}
\vartheta=1\quad\text{near }\mathcal{H}_{\tau}\setminus\mathcal N,
\qquad
\operatorname{supp}\vartheta\subset\mathcal O .
\end{equation*}
Since $\operatorname{supp}\vartheta$ is closed in $\mathsf{D}$ and does not meet $\gamma(I)$, $\vartheta$ vanishes near $\gamma(I)$. Let $\widetilde v=\vartheta\,\widetilde v_0$, extended by zero to $\mathsf{D}$. Then
\begin{equation*}
\widetilde v\in C^\infty(\mathsf{D}),
\qquad
\widetilde v=0\quad\text{near }\gamma(I).
\end{equation*}
The cut-off does not change the Taylor expansion on $\mathcal{H}_{\tau}$, so $\widetilde v$ still satisfies \eqref{eq:borel} near $\mathcal{H}_{\tau}$. By \eqref{eq:borel} and \eqref{eq:Pwk},
\begin{equation*}
P\widetilde v\in\varphi^NC^\infty\quad\text{near }\mathcal{H}_{\tau},\ \text{for every }N,
\end{equation*}
that is, $P\widetilde v$ vanishes to infinite order on $\mathcal{H}_{\tau}=\{\varphi=0\}$. Now recalling that $R_\infty=\alpha \delta(\phi)+\tilde{v}H(\phi)$ Lemma~\ref{lem:key} gives
\begin{equation}
  F_\infty
  =
  PR_\infty-\chi\,\delta'(\varphi)
  =
  (P\widetilde{v})\,H(\varphi)
  \in C^\infty(\mathsf{D}).
  \label{eq:Finfty}
\end{equation}
The term $F_\infty$ is smooth because $P\widetilde v$ vanishes to infinite order on $\{\varphi=0\}$, and $F_\infty=0$ near $\gamma(I)$, since $\widetilde v=0$ there.

\medskip\noindent
\textbf{4. The smooth remainder.}
Set
\begin{equation}
  W=V-R_\infty,
  \qquad\text{so that}\qquad
  PW=-F_\infty\in C^\infty(\mathsf{D})
  \label{eq:W}
\end{equation}
by \eqref{eq_wave_lorentz} and \eqref{eq:Finfty}. Since $\mathsf{D}$ is globally hyperbolic, it has a Cauchy temporal function $t_{\mathsf{D}}$. Let
\begin{equation*}
C=\operatorname{supp}\chi\cup\{\gamma(\tau)\},
\end{equation*}
a compact set, choose $t_0<\min_Ct_{\mathsf{D}}$, and let
\begin{equation*}
\Sigma=\{t_{\mathsf{D}}=t_0\},
\end{equation*}
an initial spacelike Cauchy hypersurface in the past of $C$. Since $t_{\mathsf{D}}$ increases along future-directed causal curves,
\begin{equation*}
J^+(C)\subset\{t_{\mathsf{D}}\ge\min_Ct_{\mathsf{D}}\},
\end{equation*}
so $J^+(C)$ does not meet the neighbourhood $\{t_{\mathsf{D}}<\min_Ct_{\mathsf{D}}\}$ of $\Sigma$. Now:
\begin{equation*}
\begin{aligned}
&\operatorname{supp} V\subset J^+(\operatorname{supp}(\chi\,\delta'(\varphi)))\subset J^+(C)&&\text{by \eqref{eq_wave_lorentz}},\\
&\operatorname{supp}\alpha\subset J^+(\operatorname{supp}\chi)\subset J^+(C)&&\text{by Step~2},\\
&\operatorname{supp}\bigl(\widetilde v\,H(\varphi)\bigr)\subset\overline{\{f\ge\tau\}}\subset J^+(\gamma(\tau))\subset J^+(C)&&\text{by Lemma~\ref{lem_monotone}(a)}.
\end{aligned}
\end{equation*}
Hence
\begin{equation*}
W=V-\alpha\,\delta(\varphi)-\widetilde v\,H(\varphi)=0\quad\text{near }\Sigma,
\end{equation*}
so $W$ solves $PW=-F_\infty$ with zero Cauchy data on $\Sigma$ and a smooth source. By well-posedness of the Cauchy problem we get that it is the unique smooth solution of this wave equation and in particular
\begin{equation}
  W\in C^\infty(\mathsf{D}).
  \label{eq:W-smooth}
\end{equation}

\medskip\noindent
\textbf{5. Conclusion.}
Since $\operatorname{supp} V\subset J^+(\operatorname{supp}\chi\cap\mathcal{H}_{\tau})$, Lemma~\ref{lem_monotone}(b) gives
\begin{equation*}
\operatorname{supp} V\cap\mathsf{D}_\gamma\subset\{\varphi\ge0\}.
\end{equation*}
By construction, $\operatorname{supp} R_\infty\subset\{\varphi\ge0\}$. So the smooth function $W=V-R_\infty$ vanishes on $\{\varphi<0\}$, that is,
\begin{equation*}
W=W\,H(\varphi).
\end{equation*}
Going back to $V=R_\infty+W$, we obtain
\begin{equation*}
V=\alpha\,\delta(\varphi)+v\,H(\varphi),\qquad v=\widetilde v+W\in C^\infty(\mathsf{D}),
\end{equation*}
which finishes the proof of~\eqref{eq:main}.

\label{rem_whole_diamond}
It is important that the null cones foliate the whole of $\mathsf{D}_\gamma$, and not only a neighbourhood of $\overlineM$. This is so even if $\operatorname{supp}\chi\subsetM$. Indeed, by finite speed of propagation, $V_\tau$ in $M$ depends on the geometry of the region
\begin{equation*}
J^+(\operatorname{supp}\chi)\cap J^-(\overlineM),
\end{equation*}
which in general is not contained in $\overlineM$: causal curves, and in particular the null generators of $\mathcal H_\tau$, may leave $\overlineM$ and come back. Without the foliation outside $\overlineM$, the cone $\mathcal H_\tau$ could develop caustics there, and singularities of $V_\tau$ could re-enter $M$ away from $\mathcal H_\tau$. The progressive wave representation of Proposition~\ref{prop_prog_wave} would then fail in $M$.

\label{thm_carleman}
Let $\psi\in C^\infty(\mathsf{D})$ satisfy $g(d\psi,d\psi)<0$ and such that $\psi$ increases along future-directed timelike curves. Let $\tilde\psi = e^{\zeta\psi}$. Then there is $\zeta_0>0$ such that the following holds for every $\zeta\ge\zeta_0$. There are $C,\sigma_0>0$ such that for every $u\in C^\infty(X_\tau)$ one has,
\begin{multline*}
\sigma^3|e^{\sigma\tilde\psi}u|^2_{\mathcal H_\tau} + \sigma|e^{\sigma\tilde\psi}Lu|^2_{\mathcal H_\tau} + \sigma^3\|e^{\sigma\tilde\psi}u\|^2_{Q_\tau} + \sigma\|e^{\sigma\tilde\psi}\nabla_hu\|^2_{Q_\tau}\\
\le\; C\,\|e^{\sigma\tilde\psi}Pu\|^2_{Q_\tau} \;+\; C\Bigl(\sigma^3|e^{\sigma\tilde\psi}u|^2_{\Gamma_\tau} + \sigma|e^{\sigma\tilde\psi}\partial_\nu u|^2_{\Gamma_\tau} + \sigma|e^{\sigma\tilde\psi}\nabla_h^{\tan}u|^2_{\Gamma_\tau}\Bigr),
\end{multline*}
for all $\sigma \geq \sigma_0$.

\label{rem_powers}
The Carleman estimate of Theorem~\ref{thm_carleman} is closely related to~\cite[Proposition~2.5]{oksanen2026semiglobaluniquenesslorentziancalderon}. There, the terms on the null hypersurface come with the same powers $\sigma^3$ and $\sigma$, but the bulk terms are stronger: $\sigma^3$ and $\sigma$ are replaced by $\sigma^4$ and $\sigma^2$. Moreover, the weight is $e^{\sigma\psi}$ itself, without convexification. This reflects the fact that the level sets of $\psi$ are spacelike, since $d\psi$ is timelike. So information is propagated across spacelike hypersurfaces, a direction in which the Cauchy problem for the wave equation is well posed. As a consequence, the estimate is semiclassically elliptic, and not only subelliptic contrasting to a standard Carleman estimate. See as well \cite[Remark~C.9]{oksanen2026semiglobaluniquenesslorentziancalderon}.

Notice that the estimate of~\cite[Proposition~2.5]{oksanen2026semiglobaluniquenesslorentziancalderon} does not apply in our setting. There, the lateral boundary is timelike and the Cauchy data vanish on it, while here $\partialM$ has no causal type and its Cauchy data appear on the right-hand side. We expect however that Theorem~\ref{thm_carleman} also holds without the loss of a half derivative, that is, with $\sigma^4$ and $\sigma^2$ in the bulk terms. We do not pursue this, since Theorem~\ref{thm_carleman} suffices for the proof of Theorem~\ref{thm_main}, and its proof is relatively short and self-contained.

\label{lem_algebra}
Let $V$ be a finite dimensional vector space with a Lorentzian metric $g$.
Let $Y_1, Y_2, Z \in V$ and suppose that $Y_1$ is timelike, $Y_2$ is causal and that $Y_1$ and $Y_2$ are in the same timecone. Then
\begin{equation}\label{abs_nonpos}
2 g(Z, Y_1) g(Z, Y_2) - g(Z, Z) g(Y_1, Y_2) \ge 0.
\end{equation}
The above inequality is strict or $Z = cY_2$ for some $c \in \mathbb R$.

\label{cor_algebra}
Let $V$ be a finite dimensional vector space with a Lorentzian metric $g$.
Let $Y_1, Y_2, Z \in V$ and suppose that $Y_1$ is timelike, $Y_2$ is causal and that $Y_1$ and $Y_2$ are in the same timecone.
Let a subspace $W \subset V$ satisfy $V = \mathbb R Y_2 \oplus W$, and let $g^+$ be an inner product on $W$.
Then there is $\epsilon > 0$ such that
\begin{equation}\label{abs_nonpos_compl}
\epsilon\, g^+(Z', Z') \le 2 g(Z, Y_1) g(Z, Y_2) - g(Z, Z) g(Y_1, Y_2),
\end{equation}
where $Z = sY_2 + Z' \in \mathbb R Y_2 \oplus W$.

Let $\Phi(Z)$ denote the right-hand side of \eqref{abs_nonpos_compl}, a quadratic form in $Z$. By Lemma~\ref{lem_algebra}, $\Phi$ can only degenerate in the direction $Y_2$, so we distinguish the cases $Y_2$ timelike and $Y_2$ null.

If $Y_2$ is timelike, then $\Phi(cY_2)=c^2g(Y_2,Y_1)g(Y_2,Y_2)>0$ for $c\neq0$, so $\Phi$ is positive definite on $V$ by Lemma~\ref{lem_algebra}, and \eqref{abs_nonpos_compl} follows. If $Y_2$ is null, then $\Phi(Y_2)=0$, and the polar form of $\Phi$ satisfies
\begin{align*}
\Phi(Y_2,Z')&=g(Y_2,Y_1)g(Z',Y_2)+g(Z',Y_1)g(Y_2,Y_2)-g(Y_2,Z')g(Y_1,Y_2)\\
&=g(Z',Y_1)g(Y_2,Y_2)=0;
\end{align*}
hence $\Phi(sY_2+Z')=\Phi(Z')$. By Lemma~\ref{lem_algebra}, $\Phi(Z')>0$ unless $Z'\in\mathbb R Y_2\cap W=\{0\}$. So $\Phi$ is positive definite on $W$, and $\epsilon$ exists by compactness of the unit sphere of $g^+$.

\label{lem_recovery}
Let $\tau\in[\tau_a,\tau_b]$. Then
\begin{equation}\label{eq_recovery}
\bar q\,\alpha+2Lw_\tau+\theta w_\tau=0\ \text{ on }\mathcal{H}_{\tau},\qquad (\Box_g+q_1)w_\tau=-\bar q\,v_{2,\tau}\ \text{ in }Q_\tau .
\end{equation}
In particular, ~\eqref{eq:alpha-lower} implies $|\bar q|^2\le C \bigl(|Lw_\tau|^2+|w_\tau|^2\bigr)$ on $\mathcal{H}_{\tau}\cap K$.

The manifold $(\mathcal{M}, g)$ is~\textit{globally hyperbolic} if
    \begin{enumerate}
        \item \label{point_one} there is no closed causal curve,

        \item \label{point_two} the causal diamonds $J^+(p) \cap J^-(q)$ are compact sets for all $p, q \in \mathcal{M}$.
    \end{enumerate}

\label{prop_of_globhyper}
    The following are equivalent for $(\mathcal{M}, g)$.

\begin{enumerate}
    \item $(\mathcal{M}, g)$ is globally hyperbolic.

    \item There exists a smooth spacelike Cauchy surface in $\mathcal{M}$.

    \item There exists a temporal function, that is a smooth function $\tau : \mathcal{M} \to \mathbb R$ that satisfies $g(d \tau,d \tau)<0$, $d \tau $ is future-directed, and all level sets $\Sigma_t=\tau^{-1}(t)$ are smooth spacelike Cauchy surfaces. The function $\tau$ can be taken surjective and such that its restriction to any inextendible future-directed causal curve is strictly increasing and surjective onto $\mathbb R$. Moreover, $\mathcal{M}$ is diffeomorphic to $\mathbb R \times \Sigma$ via  $F :\mathbb R \times \Sigma_0 \to \mathcal{M}$ with
    \begin{equation}
        (F^*g)(t,x)=c(t,x)(-dt^2+h_t(x)),
    \end{equation}
 where $c>0$ is smooth, $h_t(x)$ is a Riemannian metric on $\Sigma_0$ smoothly depending on $t$ and $t=\tau$.
\end{enumerate}

\label{prop_wave_lorentz}
  Let $(\mathcal{M}, g)$ be globally hyperbolic and $P$ a normally hyperbolic operator. Then for any $F \in \mathcal{E}^\prime(\mathcal{M})$ there exists a unique $u \in \mathcal{D}^\prime (\mathcal{M})$ such that
 \begin{equation}
\begin{cases}
    P u=F  \quad \textnormal{in } \mathcal{M},\\
    \operatorname{supp} (u) \subset J^+(\operatorname{supp} (F)).
    \end{cases}
\end{equation}
